import 'package:flutter/material.dart';
class SummaryCard extends StatelessWidget { final String title,value; final IconData icon; const SummaryCard({super.key,required this.title,required this.value,required this.icon}); @override Widget build(BuildContext context)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Row(children:[CircleAvatar(child:Icon(icon)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title),Text(value,style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold))]))]))); }
